 18	import io.github.julianperge.modular_planters.registry.MPBlockEntities;
 19	import net.minecraft.core.BlockPos;
 20	import net.minecraft.core.Direction;
 21	import net.minecraft.server.level.ServerLevel;
 22	import net.minecraft.world.level.Level;
 23	import net.minecraft.world.level.block.entity.BlockEntity;
 24	import net.minecraft.world.level.block.state.BlockState;
 25	import net.neoforged.neoforge.transfer.ResourceHandler;
 26	import net.neoforged.neoforge.transfer.item.ItemResource;
 27	import org.jspecify.annotations.Nullable;
 28	
 29	import java.util.ArrayList;
 30	import java.util.Arrays;
 31	import java.util.List;
 32	import java.util.Map;
 33	
 34	public class CoreBlockEntity extends BlockEntity {
 35	    private static final int RESCAN_INTERVAL = 20;
 36	
 37	    private ScanResult<BlockPos> lastScan = new ScanResult<>(Problem.WAITING_FOR_CHUNKS, null, Map.of());
 38	    private @Nullable Multiblock multiblock;
 39	    private @Nullable PowerPool power;
 40	    private @Nullable FertilizerPool fertilizer;
 41	    private @Nullable OutputSink outputs;
 42	    private @Nullable MeLink me;
 43	    private @Nullable ResourceHandler<ItemResource> items;
 44	    private boolean dirty = true;
 45	    private boolean poolsStale;
 46	    private long wantedLastTick;
 47	
 48	    public CoreBlockEntity(BlockPos pos, BlockState state) {
 49	        super(MPBlockEntities.CORE.get(), pos, state);
 50	    }
 51	
 52	    public static void serverTick(Level level, BlockPos pos, BlockState state, CoreBlockEntity core) {
 53	        if (core.dirty || (level.getGameTime() + core.tickOffset()) % RESCAN_INTERVAL == 0) {
 54	            core.scan(level);
 55	        }
 56	        if (level instanceof ServerLevel serverLevel) {
 57	            core.tickPlanters(serverLevel);
 58	        }
 59	    }
 60	
 61	    // The pools are null while the core waits for an unloaded chunk, and the planters then keep their progress without ticking.
 62	    private void tickPlanters(ServerLevel level) {
 63	        if (multiblock == null || power == null || fertilizer == null || outputs == null || !allPartsLoaded()) {
 64	            wantedLastTick = 0;
 65	            return;
 66	        }
 67	        MeLink link = onlineMe();
 68	        if (link != null && wantedLastTick > 0) {
 69	            power.refillFrom(link, wantedLastTick);
 70	        }
 71	        TickContext context = new TickContext(level, level.getRandom(), AteBridge.numbers(), power, fertilizer.budget(), outputs);
 72	        long wanted = 0;
 73	        for (BlockPos pos : multiblock.planters()) {
 74	            if (level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
 75	                planter.tickFromCore(context);
 76	                wanted += planter.lastWanted();
 77	            }
 78	        }
 79	        wantedLastTick = wanted;
 80	        if (link != null && (level.getGameTime() + tickOffset()) % MPConfig.ME_INTERVAL.get() == 0) {
 81	            outputs.moveExportsInto(link);
 82	            fertilizer.topUpFrom(link);
 83	        }
 84	    }
 85	
 86	    // This returns the link only while it is online, and a removed link counts as absent and marks the pools stale so the next scan rebuilds them without it.
 87	    private @Nullable MeLink onlineMe() {
 88	        if (me == null) {
 89	            return null;
 90	        }
 91	        if (me.isRemoved()) {
 92	            markPoolsStale();
 93	            return null;
 94	        }
 95	        return me.online() ? me : null;
 96	    }
 97	
 98	    // Cores spread their rescans and ME transfers over different ticks by position, so many cores don't all work on the same tick.
 99	    public int tickOffset() {
100	        return Math.floorMod(worldPosition.hashCode(), RESCAN_INTERVAL);
101	    }
102	
103	    public void markDirty() {
104	        dirty = true;
105	    }
106	
107	    // A pooled block was removed, and a replacement at the same position gives an equal scan result, so the next scan must rebuild the pools anyway.
108	    private void markPoolsStale() {
109	        dirty = true;
110	        poolsStale = true;
111	    }
112	
113	    public ScanResult<BlockPos> lastScan() {
114	        return lastScan;
115	    }
116	
117	    public @Nullable Multiblock multiblock() {
118	        return multiblock;
119	    }
120	
121	    public @Nullable PowerPool power() {
122	        return power;
123	    }
124	
125	    public @Nullable FertilizerPool fertilizer() {
126	        return fertilizer;
127	    }
128	
129	    public @Nullable OutputSink outputs() {
130	        return outputs;
131	    }
132	
133	    public @Nullable ResourceHandler<ItemResource> items() {
134	        return items;
135	    }
136	
137	    public MeStatus meStatus() {
138	        return me == null || me.isRemoved() ? MeStatus.NONE : me.status();
139	    }
140	
141	    public boolean allPartsLoaded() {
142	        return level != null && (multiblock == null || multiblock.all().stream().allMatch(level::isLoaded));
143	    }
144	
145	    @Override
146	    public void onLoad() {
147	        super.onLoad();
148	        dirty = true;
149	    }
150	
151	    private void scan(Level level) {
152	        dirty = false;
153	        boolean rebuild = poolsStale;
154	        poolsStale = false;
155	        ScanResult<BlockPos> result = StructureScanner.scan(worldPosition,
156	                pos -> Arrays.stream(Direction.values()).map(pos::relative).toList(),
157	                pos -> typeAt(level, pos), MPConfig.PART_CAP.get());
158	        if (result.equals(lastScan) && !rebuild) {
159	            return;
160	        }
161	        lastScan = result;
162	        if (result.problem() == Problem.WAITING_FOR_CHUNKS) {
163	            // The multiblock is kept so a structure with an unloaded part pauses instead of unforming, while the pools are dropped so nothing touches a block entity in an unloaded chunk.
164	            power = null;
165	            fertilizer = null;
166	            outputs = null;
167	            me = null;
168	            items = null;
169	        } else {
170	            Multiblock previous = multiblock;
171	            multiblock = result.formed() ? Multiblock.from(result) : null;
172	            if (previous != null) {
173	                stopPlanters(level, previous.planters(), multiblock == null ? List.of() : multiblock.planters());
174	            }
175	            buildPools(level);
176	        }
177	        level.invalidateCapabilities(worldPosition);
178	        setChanged();
179	    }
180	
181	    // No scan runs once the core is gone, so the core stops its planters here, or they would stay ACTIVE and GROWING.
182	    @Override
183	    public void preRemoveSideEffects(BlockPos pos, BlockState state) {
184	        if (level != null && multiblock != null) {
185	            stopPlanters(level, multiblock.planters(), List.of());
186	        }
187	    }
188	
189	    private static void stopPlanters(Level level, List<BlockPos> planters, List<BlockPos> stillFormed) {
190	        for (BlockPos pos : planters) {
191	            if (!stillFormed.contains(pos) && level.isLoaded(pos)
192	                    && level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
193	                planter.stopFromCore();
194	            }
195	        }
196	    }
197	
198	    private void buildPools(Level level) {
199	        if (multiblock == null) {
200	            power = null;
201	            fertilizer = null;
202	            outputs = null;
203	            me = null;
204	            items = null;
205	            return;
206	        }
207	        power = new PowerPool(blockEntities(level, multiblock.power(), PowerBlockEntity.class), this::markPoolsStale);
208	        fertilizer = new FertilizerPool(blockEntities(level, multiblock.fertilizer(), FertilizerBlockEntity.class), this::markPoolsStale);
209	        BlockPos mePos = multiblock.me();
210	        me = mePos != null && level.getBlockEntity(mePos) instanceof MeLink link ? link : null;
211	        outputs = new OutputSink(blockEntities(level, multiblock.export(), ExportBlockEntity.class), me, this::markPoolsStale);
212	        items = DoorwayHandlers.items(fertilizer, outputs);
213	    }
214	
215	    private static <T extends BlockEntity> List<T> blockEntities(Level level, List<BlockPos> positions, Class<T> type) {
216	        List<T> found = new ArrayList<>();
217	        for (BlockPos pos : positions) {
218	            BlockEntity blockEntity = level.getBlockEntity(pos);
219	            if (type.isInstance(blockEntity)) {
220	                found.add(type.cast(blockEntity));
221	            }
222	        }
223	        return found;
224	    }
225	
226	    private static PartType typeAt(Level level, BlockPos pos) {
227	        if (!level.isLoaded(pos)) {
228	            return PartType.UNLOADED;
229	        }
230	        return level.getBlockState(pos).getBlock() instanceof PartBlock part ? part.partType() : PartType.NOT_A_PART;
231	    }
232	}

