128	    public static void serverTick(Level level, BlockPos pos, BlockState state, PlanterBlockEntity planter) {
129	        if (planter.ticksSinceCore <= STALE_TICKS && ++planter.ticksSinceCore > STALE_TICKS) {
130	            planter.stopFromCore();
131	        }
132	        boolean wantActive = planter.status == PlanterStatus.GROWING || planter.status == PlanterStatus.SHORT_ON_SOIL;
133	        planter.inactiveTicks = wantActive ? 0 : Math.min(planter.inactiveTicks + 1, ACTIVE_OFF_DELAY);
134	        boolean active = state.getValue(PlanterBlock.ACTIVE);
135	        if (wantActive != active && (wantActive || planter.inactiveTicks >= ACTIVE_OFF_DELAY)) {
136	            level.setBlock(pos, state.setValue(PlanterBlock.ACTIVE, wantActive), Block.UPDATE_ALL);
137	        }
138	    }
139	
140	    public void tickFromCore(TickContext ctx) {
141	        ticksSinceCore = 0;
142	        lastDraw = 0;
143	        lastWanted = 0;
144	        boolean holding = false;
145	        if (!heldOutputs.isEmpty()) {
146	            flushHeldOutputs(ctx.outputs());
147	            setChanged();
148	            holding = !heldOutputs.isEmpty();
149	        }
150	
151	        int soilCount = soilAndModules.getAmountAsInt(SOIL);
152	        ItemStack soil = soilAndModules.getResource(SOIL).toStack(soilCount);
153	        Optional<AteBridge.PlantRecipe> recipe = seeds.size() == 0 || soil.isEmpty()
154	                ? Optional.empty() : recipes.get(ctx.level(), seeds.seed(0));
155	        if (recipe.isEmpty() || !recipe.get().soilMatches().test(soil)) {
156	            if (holding) {
157	                setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
158	                return;
159	            }
160	            seeds.resetAll();
161	            growing = 0;
162	            upgraded = 0;
163	            setStatus(PlanterStatus.IDLE);
164	            setChanged();
165	            return;
166	        }
167	
168	        int nowGrowing = Coverage.growing(seeds.size(), soilCount);
169	        ModuleKind kind1 = moduleKind(MODULE_1);
170	        ModuleKind kind2 = moduleKind(MODULE_2);
171	        int count1 = moduleCount(MODULE_1, kind1);
172	        int count2 = moduleCount(MODULE_2, kind2);
173	        List<Group> groups = Grouping.of(seeds, Coverage.assign(nowGrowing, kind1, count1, kind2, count2));
174	
175	        // Each group decides once per tick, before any pause, so a paused group still holds its claim and one decision sets both its growth time and its harvest.
176	        Map<Group, FertilizerData> fertilized = new HashMap<>();
177	        for (Group group : groups) {
178	            FertilizerData claimed = ctx.fertilizer().claim(group.size());
179	            if (claimed != null) {
180	                fertilized.put(group, claimed);
181	            }
182	        }
183	        if (holding) {
184	            setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
185	            return;
186	        }
187	
188	        growing = nowGrowing;
189	        seeds.resetFrom(growing);
190	        upgraded = Coverage.upgraded(growing, count1, count2);
191	
192	        AteNumbers numbers = ctx.numbers();
193	        float soilModifier = AteBridge.soilModifier(soil);
194	        PlanterStatus paused = null;
195	        PlanterTicker.AdvanceResult result = PlanterTicker.advance(seeds, groups,
196	                group -> processingTime(ctx, group, soilModifier, fertilized.get(group)),
197	                modules -> GrowthMath.powerPerSeedTick(numbers, modules),
198	                ctx.power().stored());
199	        lastWanted = result.energyWanted();
200	        if (result.pausedForPower()) {
201	            paused = PlanterStatus.PAUSED_FOR_POWER;
202	        } else {
203	            // This take can't fail, because advance was given ctx.power().stored() and only charges what that covers.
204	            ctx.power().tryTake(result.energyUsed());
205	            lastDraw = result.energyUsed();
206	        }
207	
208	        for (Group group : groups) {
209	            if (!seeds.ready(group.first())) {
210	                continue;
211	            }
212	            FertilizerData fertilizer = fertilized.get(group);
213	            float fertilizerYield = fertilizer != null ? fertilizer.yieldMultiplier() : 1.0f;
214	            float moduleYield = group.modules().yieldModifier(numbers);
215	            float modifier = fertilizerYield * moduleYield * (float) numbers.clocheYield();
216	            if (!ctx.outputs().hasRoomFor(listedDrops(recipe.get().drops(), modifier, group.size()))) {
217	                paused = PlanterStatus.PAUSED_EXPORT_FULL;
218	                break;
219	            }
220	            for (int seed : group.seeds()) {
221	                harvest(ctx, seed, fertilizer != null, fertilizerYield, moduleYield, modifier);
222	            }
223	            // Outputs that did not fit are held until they leave, so later groups wait instead of adding more to the pile.
224	            if (!heldOutputs.isEmpty()) {
225	                break;
226	            }
227	        }
228	
229	        if (!heldOutputs.isEmpty()) {
230	            setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
231	        } else if (paused != null) {
232	            setStatus(paused);
233	        } else if (growing < seeds.size()) {
234	            setStatus(PlanterStatus.SHORT_ON_SOIL);
235	        } else {
236	            setStatus(PlanterStatus.GROWING);
237	        }
238	        setChanged();
239	    }
240	
241	    public void stopFromCore() {
242	        lastDraw = 0;
243	        lastWanted = 0;
244	        growing = 0;
245	        upgraded = 0;
246	        setStatus(PlanterStatus.IDLE);
247	    }
248	
249	    private ModuleKind moduleKind(int slot) {
250	        return AteBridge.moduleKind(soilAndModules.getResource(slot).toStack());
251	    }
252	
253	    private int moduleCount(int slot, ModuleKind kind) {
254	        return kind == ModuleKind.NONE ? 0 : soilAndModules.getAmountAsInt(slot);
255	    }
256	
257	    private int processingTime(TickContext ctx, Group group, float soilModifier, @Nullable FertilizerData fertilizer) {
258	        float fertilizerSpeed = fertilizer != null ? fertilizer.speedMultiplier() : 1.0f;
259	        int time = GrowthMath.growthTime(ctx.numbers(), soilModifier, group.modules(), fertilizerSpeed);
260	        return NeoForge.EVENT_BUS.post(new PlanterProcessingTimeEvent(this, seeds.seed(group.first()).copy(), time))
261	                .getProcessingTime();
262	    }
263	
264	    // Each drop entry gets one more item per seed than ATE's rounding gives, because the cloche adds at most one extra item per drop and harvest.
265	    private static List<ItemStack> listedDrops(List<DropEntry> drops, float modifier, int seedCount) {
266	        List<ItemStack> listed = new ArrayList<>(drops.size());
267	        for (DropEntry entry : drops) {
268	            listed.add(new ItemStack(entry.item(), (ClocheYield.ateCount(entry.max(), modifier) + 1) * seedCount));
269	        }
270	        return listed;
271	    }
272	
273	    private void harvest(TickContext ctx, int index, boolean fertilized, float fertilizerYield, float moduleYield,
274	                         float modifier) {
275	        ItemStack stored = seeds.seed(index);
276	        ItemStack seed = NeoForge.EVENT_BUS.post(new PlanterPreHarvestEvent(this, stored.copy())).getSeed();
277	        if (!seed.isEmpty() && !ItemStack.matches(seed, stored)) {
278	            seeds.replaceSeed(index, seed.copyWithCount(1));
279	        }
280	
281	        List<ItemStack> rolled = recipes.get(ctx.level(), seed)
282	                .map(recipe -> AteBridge.rollDrops(recipe.drops(), ctx.random()))
283	                .orElse(List.of());
284	        List<ItemStack> drops = new ArrayList<>(rolled.size());
285	        List<ItemStack> extras = new ArrayList<>();
286	        for (ItemStack raw : rolled) {
287	            drops.add(raw.copyWithCount(ClocheYield.ateCount(raw.getCount(), modifier)));
288	            long kept = ClocheYield.keptMicros(raw.getCount(), fertilizerYield, moduleYield, ctx.numbers().clocheYield());
289	            int extra = clocheRemainders.addAndTakeWhole(BuiltInRegistries.ITEM.getKey(raw.getItem()).toString(), kept);
290	            if (extra > 0) {
291	                extras.add(raw.copyWithCount(extra));
292	            }
293	        }
294	
295	        PlanterPostHarvestEvent post = NeoForge.EVENT_BUS.post(
296	                new PlanterPostHarvestEvent(this, seeds.seed(index).copy(), drops));
297	        for (ItemStack drop : post.getDrops()) {
298	            hold(ctx.outputs().insert(drop));
299	        }
300	        for (ItemStack extra : extras) {
301	            hold(ctx.outputs().insert(extra));
302	        }
303	
304	        if (fertilized) {
305	            // The claim made at the start of this tick guarantees these items are there, so consuming them cannot come up short.
306	            ctx.fertilizer().consume(1);
307	        }
308	        seeds.reset(index);
309	    }
310	
311	    private void flushHeldOutputs(OutputSink outputs) {
312	        List<ItemStack> held = new ArrayList<>(heldOutputs);
313	        heldOutputs.clear();
314	        for (ItemStack stack : held) {
315	            hold(outputs.insert(stack));
316	        }
317	    }
318	
319	    // Held stacks are split to their item's stack size, because the item stack codec that saves them rejects counts above 99.
320	    private void hold(ItemStack stack) {
321	        while (!stack.isEmpty()) {
322	            heldOutputs.add(stack.split(stack.getMaxStackSize()));
323	        }
324	    }
325	
326	    private void setStatus(PlanterStatus next) {
327	        status = next;
328	    }
329	
330	    @Override
331	    public void preRemoveSideEffects(BlockPos pos, BlockState state) {
332	        if (level == null) {
333	            return;
334	        }
335	        for (SeedBin.Combo<ItemStack> combo : seeds.combos()) {
336	            dropAll(pos, combo.seed().copyWithCount(combo.count()));
337	        }
338	        seeds.clear();
339	        for (int slot = 0; slot < soilAndModules.size(); slot++) {
340	            dropAll(pos, soilAndModules.getResource(slot).toStack(soilAndModules.getAmountAsInt(slot)));
341	            soilAndModules.set(slot, ItemResource.EMPTY, 0);
342	        }
343	        heldOutputs.forEach(stack -> dropAll(pos, stack));
344	        heldOutputs.clear();
345	    }
346	
347	    private void dropAll(BlockPos pos, ItemStack stack) {
348	        while (!stack.isEmpty()) {
349	            Containers.dropItemStack(level, pos.getX(), pos.getY(), pos.getZ(), stack.split(stack.getMaxStackSize()));
350	        }
351	    }
352	
353	    @Override
354	    protected void saveAdditional(ValueOutput output) {
355	        super.saveAdditional(output);
356	        output.putString("status", status.name());
357	        if (!lastSoil.isEmpty()) {
358	            output.store("last_soil", ItemStack.CODEC, lastSoil);
359	        }
360	        ValueOutput.ValueOutputList bin = output.childrenList("seeds");
361	        for (int i = 0; i < seeds.size(); i++) {
362	            ValueOutput entry = bin.addChild();
363	            entry.store("seed", ItemStack.CODEC, seeds.seed(i));
364	            entry.putInt("progress", seeds.progress(i));
365	            entry.putBoolean("ready", seeds.ready(i));
366	        }
367	        soilAndModules.serialize(output.child("soil_and_modules"));
368	        output.store("cloche_remainders", REMAINDERS_CODEC, clocheRemainders.snapshot());
369	        ValueOutput.TypedOutputList<ItemStack> held = output.list("held_outputs", ItemStack.CODEC);
370	        heldOutputs.forEach(held::add);
371	    }
372	
373	    @Override
374	    protected void loadAdditional(ValueInput input) {
375	        super.loadAdditional(input);
376	        String savedStatus = input.getStringOr("status", "");
377	        status = Arrays.stream(PlanterStatus.values()).filter(value -> value.name().equals(savedStatus)).findFirst()
378	                .orElse(PlanterStatus.IDLE);
379	        seeds.clear();
380	        input.childrenListOrEmpty("seeds").stream().limit(SeedBin.CAPACITY).forEach(entry -> entry.read("seed", ItemStack.CODEC)
381	                .ifPresent(seed -> seeds.restore(seed, Math.max(0, entry.getIntOr("progress", 0)),
382	                        entry.getBooleanOr("ready", false))));
383	        soilAndModules.deserialize(input.childOrEmpty("soil_and_modules"));
384	        ItemStack savedSoil = soilAndModules.getResource(SOIL).toStack();
385	        lastSoil = input.read("last_soil", ItemStack.CODEC)
386	                .orElse(savedSoil.isEmpty() ? ItemStack.EMPTY : savedSoil.copyWithCount(1));
387	        clocheRemainders.load(input.read("cloche_remainders", REMAINDERS_CODEC).orElse(Map.of()));
388	        heldOutputs.clear();
389	        input.listOrEmpty("held_outputs", ItemStack.CODEC).stream().limit(HELD_OUTPUTS_CAP).forEach(heldOutputs::add);
390	    }
391	}

