  9	public final class FakeMeLink implements MeLink {
 10	    public MeStatus status;
 11	    public boolean removed;
 12	    public ItemResource filter = ItemResource.EMPTY;
 13	    public long energy;
 14	    public long modulateShortfall;
 15	
 16	    private final long capacity;
 17	    private final Map<ItemResource, Long> items = new HashMap<>();
 18	
 19	    public FakeMeLink(MeStatus status, long capacity) {
 20	        this.status = status;
 21	        this.capacity = capacity;
 22	    }
 23	
 24	    public long stored(ItemResource resource) {
 25	        return items.getOrDefault(resource, 0L);
 26	    }
 27	
 28	    public void put(ItemResource resource, long amount) {
 29	        items.merge(resource, amount, Long::sum);
 30	    }
 31	
 32	    @Override
 33	    public MeStatus status() {
 34	        return status;
 35	    }
 36	
 37	    @Override
 38	    public long insertItem(ItemResource resource, long amount, boolean simulate) {
 39	        if (status != MeStatus.ONLINE) {
 40	            return 0;
 41	        }
 42	        long total = items.values().stream().mapToLong(Long::longValue).sum();
 43	        long accepted = Math.min(amount, Math.max(0, capacity - total));
 44	        if (simulate) {
 45	            return accepted;
 46	        }
 47	        long inserted = Math.max(0, accepted - modulateShortfall);
 48	        put(resource, inserted);
 49	        return inserted;
 50	    }
 51	
 52	    @Override
 53	    public long extractItem(ItemResource resource, long amount, boolean simulate) {
 54	        if (status != MeStatus.ONLINE) {
 55	            return 0;
 56	        }
 57	        long extracted = Math.min(amount, stored(resource));
 58	        if (!simulate) {
 59	            items.merge(resource, -extracted, Long::sum);
 60	        }
 61	        return extracted;
 62	    }
 63	
 64	    @Override
 65	    public long extractEnergy(long amount, boolean simulate) {
 66	        if (status != MeStatus.ONLINE) {
 67	            return 0;
 68	        }
 69	        long extracted = Math.min(amount, energy);
 70	        if (!simulate) {
 71	            energy -= extracted;
 72	        }
 73	        return extracted;
 74	    }
 75	
 76	    @Override
 77	    public ItemResource fertilizerFilter() {
 78	        return filter;
 79	    }
 80	
 81	    @Override
 82	    public boolean isRemoved() {
 83	        return removed;
 84	    }
 85	}
